(5631657, 816000, 64446, '<td valign="top">This is a captivating image.<br/>Though the skies and the front part of the ground are sort of boring, the mountain formations and colours are outstanding. But what really makes the whole composition work are the 3 sheep, which totally contrasts with the whole scenery.</td>', 'This is a captivating image.Though the skies and the front part of the ground are sort of boring, the mountain formations and colours are outstanding. But what really makes the whole composition work are the 3 sheep, which totally contrasts with the whole scenery.', '2009-09-02 00:15:36.000000', NULL, 1),
(5631660, 816777, 64446, '<td valign="top">Intriguing the nuances and separation of colours: the sand, the water, the recife and the sky. Smart composition...</td>', 'Intriguing the nuances and separation of colours: the sand, the water, the recife and the sky. Smart composition...', '2009-09-02 00:15:49.000000', NULL, 1),
